import{_ as i,C as r,o as s,c as n,a2 as t,E as o}from"./chunks/framework.CHjbm2Wd.js";const f=JSON.parse('{"title":"NPR 7150.2 & software assurance","description":"Software classes, lifecycle evidence, assurance, and how to talk about compliance honestly.","frontmatter":{"title":"NPR 7150.2 & software assurance","description":"Software classes, lifecycle evidence, assurance, and how to talk about compliance honestly."},"headers":[],"relativePath":"flight/npr-7150.md","filePath":"flight/npr-7150.md","lastUpdated":1792993690000}'),l={name:"flight/npr-7150.md"};function d(c,e,p,h,u,m){const a=r("Quiz");return s(),n("div",null,[e[0]||(e[0]=t(`<h1 id="npr-7150-2-software-assurance" tabindex="-1">NPR 7150.2 &amp; software assurance <a class="header-anchor" href="#npr-7150-2-software-assurance" aria-label="Permalink to &quot;NPR 7150.2 &amp; software assurance&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Why this matters</p><p>NASA NPR 7150.2 is the software engineering procedural requirement that shows up in lunar-lander job descriptions. You do not need to memorize it. You need to understand software criticality classes, the lifecycle evidence it expects, and how to map your project’s practices to that language without overclaiming.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Explain the purpose and scope of NPR 7150.2.</li><li>Distinguish software classes A–E and what drives them.</li><li>Map lifecycle activities to evidence artifacts.</li><li>Explain software assurance and IV&amp;V.</li><li>Build a tailoring/compliance crosswalk for a small project.</li><li>Avoid the common overclaim.</li></ul><h2 id="what-npr-7150-2-is" tabindex="-1">What NPR 7150.2 is <a class="header-anchor" href="#what-npr-7150-2-is" aria-label="Permalink to &quot;What NPR 7150.2 is&quot;">​</a></h2><p>NPR 7150.2 is NASA’s procedural requirement for software engineering. It establishes requirements for:</p><ul><li>software lifecycle processes,</li><li>requirements and design,</li><li>implementation and integration,</li><li>verification and validation,</li><li>configuration management,</li><li>quality assurance,</li><li>safety and security,</li><li>acquisition and supplier management,</li><li>training and risk management.</li></ul><p>It applies to NASA software and is often flowed down to contractors. A commercial lunar lander is not automatically bound by it, but the structure is a useful benchmark and a common interview vocabulary.</p><h2 id="software-classes" tabindex="-1">Software classes <a class="header-anchor" href="#software-classes" aria-label="Permalink to &quot;Software classes&quot;">​</a></h2><p>NPR 7150.2 classifies software by criticality, from <strong>Class A</strong> (highest) to <strong>Class E</strong> (lowest). The class drives the rigor of the lifecycle, documentation, reviews, testing, and assurance.</p><p>The classification is based on the consequences of failure, including:</p><ul><li>human safety,</li><li>mission loss,</li><li>major facility or system damage,</li><li>significant cost or schedule impact,</li><li>performance/quality impact only.</li></ul><p>Exact class definitions and tailoring rules are in the NPR and the companion software engineering handbook. Do not guess a class for a real program; use the program’s classification process.</p><p>For a lunar lander, the descent guidance and flight control software is typically high-criticality. A ground analysis script or a developer tool is much lower. The same team can produce both, but they should not receive the same process weight.</p><h2 id="lifecycle-evidence" tabindex="-1">Lifecycle evidence <a class="header-anchor" href="#lifecycle-evidence" aria-label="Permalink to &quot;Lifecycle evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Typical evidence</th></tr></thead><tbody><tr><td><strong>Concept</strong></td><td>Concept of operations, software architecture, risk list</td></tr><tr><td><strong>Requirements</strong></td><td>Software requirements specification, traceability, interface requirements</td></tr><tr><td><strong>Design</strong></td><td>Architecture/design description, interface control documents, analysis</td></tr><tr><td><strong>Implementation</strong></td><td>Source code, coding standard, static analysis, unit tests</td></tr><tr><td><strong>Integration</strong></td><td>Build records, integration test plan/results, configuration index</td></tr><tr><td><strong>Verification</strong></td><td>Test plans, procedures, logs, coverage, requirements trace</td></tr><tr><td><strong>Validation</strong></td><td>Mission-level scenarios, independent review, acceptance</td></tr><tr><td><strong>Operations</strong></td><td>User guide, operations procedures, anomaly reports</td></tr><tr><td><strong>Maintenance</strong></td><td>Change requests, regression results, release notes</td></tr></tbody></table><p>The evidence should be <strong>objective</strong>: a test log, a coverage report, a review record, a signed configuration index. A slide that says “tested” is not evidence.</p><h2 id="software-assurance-and-iv-v" tabindex="-1">Software assurance and IV&amp;V <a class="header-anchor" href="#software-assurance-and-iv-v" aria-label="Permalink to &quot;Software assurance and IV&amp;V&quot;">​</a></h2><p><strong>Software assurance</strong> is the set of planned and systematic activities that give confidence that the software is safe, secure, and reliable. It is broader than testing:</p><ul><li>independent review and audit,</li><li>process compliance,</li><li>hazard analysis,</li><li>static analysis,</li><li>configuration management,</li><li>problem reporting and disposition,</li><li>supplier oversight.</li></ul><p><strong>IV&amp;V</strong> is independent verification and validation: a team outside the development team performs analysis and testing. It is most valuable when the software is high-criticality and the development team is too close to the design.</p><p>For a small project, you can approximate the spirit:</p><ul><li>have someone else review the requirements and tests,</li><li>run static analysis and coverage,</li><li>keep a problem-report log,</li><li>archive the build and test evidence,</li><li>write a hazard analysis for the descent modes.</li></ul><h2 id="tailoring" tabindex="-1">Tailoring <a class="header-anchor" href="#tailoring" aria-label="Permalink to &quot;Tailoring&quot;">​</a></h2><p>NPR 7150.2 allows tailoring. A small project does not need every document, but it should document:</p><ul><li>which requirements apply,</li><li>which are tailored out and why,</li><li>what evidence replaces them,</li><li>who approved the tailoring.</li></ul><p>A tailoring matrix is a table:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Requirement | Applicable? | Tailoring | Evidence | Approval</span></span>
<span class="line"><span>NPR 7150.2 §... | Yes | None | SRS, trace matrix | ...</span></span>
<span class="line"><span>NPR 7150.2 §... | No | Small-team process | Peer review record | ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>This is the honest way to use the standard. “We follow NPR 7150.2” without a matrix is a slogan.</p><h2 id="a-crosswalk-for-your-capstone" tabindex="-1">A crosswalk for your capstone <a class="header-anchor" href="#a-crosswalk-for-your-capstone" aria-label="Permalink to &quot;A crosswalk for your capstone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>Your evidence</th></tr></thead><tbody><tr><td>Requirements</td><td><code>docs/requirements.md</code> with IDs and test links</td></tr><tr><td>Architecture</td><td><code>docs/architecture.md</code> with data flow and rate groups</td></tr><tr><td>Coding standard</td><td><code>.clang-tidy</code>, compiler warnings, MISRA subset</td></tr><tr><td>Unit tests</td><td><code>tests/</code> with coverage report</td></tr><tr><td>Integration tests</td><td>SIL harness with logs</td></tr><tr><td>Verification</td><td>Trace matrix and test report</td></tr><tr><td>Configuration management</td><td>Git tag, build script, artifact hash</td></tr><tr><td>Problem reporting</td><td><code>docs/problems.md</code> with dispositions</td></tr><tr><td>Safety</td><td>Hazard analysis and fault tree</td></tr><tr><td>Independent review</td><td>A peer review record or a second-agent review</td></tr></tbody></table><p>You do not need to call it “NPR compliant.” You can say: “I used NPR 7150.2 as a checklist to structure the evidence.”</p><h2 id="interview-language" tabindex="-1">Interview language <a class="header-anchor" href="#interview-language" aria-label="Permalink to &quot;Interview language&quot;">​</a></h2><p>Good:</p><ul><li>“I classified the descent software as high-criticality and applied requirements traceability, unit/integration testing, coverage, and fault injection.”</li><li>“I tailored the documentation for a small project and recorded the rationale.”</li><li>“I can show the trace matrix, test logs, and build record.”</li></ul><p>Bad:</p><ul><li>“I know NPR 7150.2” (without examples).</li><li>“We were compliant” (without a tailoring matrix and audit evidence).</li><li>“Testing proves it is safe” (testing supports confidence; it does not prove safety by itself).</li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Read the NPR 7150.2 table of contents and pick five requirements relevant to your capstone.</li><li>Build a tailoring/crosswalk table with evidence for each.</li><li>Write a hazard analysis for three descent faults: stale nav, stuck throttle, and altimeter dropout.</li><li>Map each hazard to a detection, isolation, and recovery action.</li><li>Ask someone to review the evidence package and list what they cannot verify.</li></ol>`,39)),o(a,{question:"What is the honest way to use NPR 7150.2 on a small commercial project?",options:"Claim full compliance in the README|Use it as a tailoring checklist, document applicability and evidence, and avoid claiming compliance without an audit|Ignore it; it only applies to NASA civil servants|Copy the standard into the repository",answer:"1",explanation:"Tailoring is part of the standard’s process. Document what applies, what does not, what evidence exists, and who approved it. Do not claim compliance you cannot audit."}),e[1]||(e[1]=t('<h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://nodis3.gsfc.nasa.gov/displayDir.cfm?t=NPR&amp;c=7150&amp;s=2" target="_blank" rel="noreferrer">NPR 7150.2</a> — the requirement.</li><li><a href="https://swehb.nasa.gov/" target="_blank" rel="noreferrer">NASA Software Engineering Handbook</a> — practical guidance and checklists.</li><li><a href="https://standards.nasa.gov/" target="_blank" rel="noreferrer">NASA-STD-8739.8</a> — software assurance.</li><li><a href="https://swehb.nasa.gov/" target="_blank" rel="noreferrer">NASA Software Safety Guidebook</a> — hazard analysis and safety.</li></ul><p>Next: <a href="./fault-protection.html">fault protection &amp; mode logic</a>.</p>',3))])}const w=i(l,[["render",d]]);export{f as __pageData,w as default};
